      "causa_raiz": "Tempo de GPU crítico em 30.19ms (acima do orçamento de 16.7ms para 60 FPS), com 514 violações registradas. Como a contagem de Draw Calls (914) está confortável dentro do orçamento de 2579, o gargalo reside na taxa de preenchimento (fill-rate), alto custo de fragment shader, sombras dinâmicas de alta resolução ou render scale elevado para a GTX 1650.",
      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class DynamicGpuPerformanceManager : MonoBehaviour
{
    [Header("Metas de Desempenho")]
    [SerializeField] private float targetFrameTimeMs = 16.67f;
    [SerializeField] private float toleranceMs = 1.5f;

    [Header("Limites de Escala de Renderização")]
    [Range(0.5f, 1.0f)] [SerializeField] private float minRenderScale = 0.65f;
    [Range(0.5f, 1.0f)] [SerializeField] private float maxRenderScale = 1.0f;
    [SerializeField] private float scaleStep = 0.05f;
    [SerializeField] private float adjustmentInterval = 0.5f;

    private float currentScale = 1.0f;
    private float timer = 0f;
    private FrameTiming[] timings = new FrameTiming[1];

    private void Start()
    {
        currentScale = maxRenderScale;
        ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        QualitySettings.shadowCascades = 2;
        QualitySettings.shadowDistance = Mathf.Min(QualitySettings.shadowDistance, 40f);
    }

    private void Update()
    {
        timer += Time.unscaledDeltaTime;
        if (timer < adjustmentInterval) return;
        timer = 0f;

        FrameTimingManager.CaptureFrameTimings();
        uint captured = FrameTimingManager.GetLatestTimings(1, timings);

        float gpuTime = captured > 0 ? (float)timings[0].gpuFrameTime : (Time.unscaledDeltaTime * 1000f);

        if (gpuTime > (targetFrameTimeMs + toleranceMs) && currentScale > minRenderScale)
        {
            currentScale = Mathf.Max(minRenderScale, currentScale - scaleStep);
            ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        }
        else if (gpuTime < (targetFrameTimeMs - toleranceMs) && currentScale < maxRenderScale)
        {
            currentScale = Mathf.Min(maxRenderScale, currentScale + scaleStep);
            ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
        }
    }
}",
      "explicacao_didatica": "O computador está gastando muito tempo para pintar cada pixel na tela (gargalo de GPU/Fill-rate), e não para emitir ordens de desenho (Draw Calls). Para corrigir isso sem perder fluidez na taxa de 60 FPS, criamos um gerenciador que monitora o tempo de GPU e reduz de maneira sutil a resolução interna de renderização e a distância das sombras quando o hardware sofre lentidão, restaurando-a assim que o peso visual diminui. Além disso, o script foi projetado para reaproveitar estruturas de dados em memória, prevenindo coletas do Garbage Collector."
    }
  ],
  "dicas_level_design": null
}

